   283	      hostname: hostname(),
   284	      command: 'provider-process-registry mutation',
   285	      acquiredAt: new Date().toISOString(),
   286	      lockId: randomUUID(),
   287	      processStartTimeMs: currentProcessStartTimeMs(),
