   398	export function transferProviderProcessSlotToProvider(
   399	  file: string | null,
   400	  token: string | null,
   401	  identity: {
   402	    pid: number;
   403	    pgid: number | null;
   404	    spawnedAt: string;
   405	    startFingerprint: string | null;
   406	    processGroupIsolated: boolean;
   407	  },
   408	  lockTiming: ProviderRegistryLockTiming = {},
   409	): boolean {
   410	  if (!file || !token) return false;
   411	  if (
   412	    !Number.isInteger(identity.pid) || identity.pid <= 0
   413	    || !identity.processGroupIsolated
   414	    || !Number.isInteger(identity.pgid) || (identity.pgid ?? 0) <= 0
   415	  ) return false;
   416	  const dir = dirname(file);
   417	  return withProviderRegistryLock(dir, () => {
   418	    const occupant = readSlotOccupant(file);
   419	    if (occupant.state !== 'valid' || occupant.token !== token) return false;
   420	    const next: ProviderProcessSlotFileMeta = {
   421	      ...(occupant.meta as unknown as ProviderProcessSlotFileMeta),
   422	      pid: identity.pid,
   423	      providerPid: identity.pid,
   424	      providerPgid: identity.pgid!,
   425	      providerSpawnedAt: identity.spawnedAt,
   426	      providerStartFingerprint: identity.startFingerprint ?? undefined,
   427	      providerProcessGroupIsolated: true,
   428	      token,
   429	    };
   430	    const temporary = `${file}.${token}.transfer`;
   431	    writeFileSync(temporary, JSON.stringify(next), { encoding: 'utf8', flag: 'wx', mode: 0o600 });
   432	    try {
   433	      // Registry lock + exact token check makes this replacement ownership-safe.
   434	      renameSync(temporary, file);
   435	    } finally {
   436	      try { unlinkSync(temporary); } catch { /* rename already consumed it */ }
   437	    }
   438	    return true;
   439	  }, lockTiming);
   440	}
