   471	// Codex turn.completed usage scan (CHK-001)
   472	// ---------------------------------------------------------------------------
   473	
   474	/**
   475	 * Scan codex `exec --json` stdout for the LAST `{"type":"turn.completed",
   476	 * "usage":{...}}` event and return its raw usage object (own-property guarded),
   477	 * or null when no turn.completed usage event is present. Line-streamed with a
   478	 * BOUNDED parse buffer: only the current line and the last usage object are held,
   479	 * so a flooding host cannot accumulate per-line state.
   480	 */
   481	export function scanCodexTurnCompletedUsage(stdout: string): unknown | null {
   482	  if (typeof stdout !== 'string' || stdout.length === 0) return null;
   483	  let last: unknown = null;
   484	  let index = 0;
   485	  const len = stdout.length;
   486	  while (index <= len) {
   487	    let newline = stdout.indexOf('\n', index);
   488	    if (newline === -1) newline = len;
   489	    const line = stdout.slice(index, newline).trim();
   490	    index = newline + 1;
   491	    if (line.length > 0) {
   492	      let parsed: unknown;
   493	      try {
   494	        parsed = JSON.parse(line);
   495	      } catch {
   496	        parsed = undefined;
   497	      }
   498	      if (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) {
   499	        const event = parsed as Record<string, unknown>;
   500	        const type = Object.prototype.hasOwnProperty.call(event, 'type') ? event.type : undefined;
   501	        if (type === 'turn.completed') {
   502	          const usage = Object.prototype.hasOwnProperty.call(event, 'usage') ? event.usage : undefined;
   503	          if (typeof usage === 'object' && usage !== null && !Array.isArray(usage)) {
   504	            last = usage;
   505	          }
   506	        }
   507	      }
   508	    }
   509	    if (newline === len) break;
   510	  }
   511	  return last;
   512	}
