   517	
   518	/** B-3ddc: a scanned codex failure event (last-wins across both event types). */
   519	export interface CodexTurnFailedEvent {
   520	  /** 'turn.failed' or 'error' — whichever matching event came LAST. */
   521	  eventType: string;
   522	  /** The extractable string message, or null when the event carried none. */
   523	  message: string | null;
   524	}
   525	
   526	/**
   527	 * B-3ddc: scan codex `exec --json` output for the LAST failure event — a
   528	 * `{"type":"turn.failed","error":{"message":...}}` or a terminal
   529	 * `{"type":"error","message":...}` line — mirroring the bounded
   530	 * scanCodexTurnCompletedUsage walk (only the current line and the last match
   531	 * are held; own-property guarded). A matching event with no extractable
   532	 * string message still counts as a failure (message: null); last-wins applies
   533	 * ACROSS both event types. Returns null when no failure event is present.
   534	 */
   535	export function scanCodexTurnFailed(text: string): CodexTurnFailedEvent | null {
   536	  if (typeof text !== 'string' || text.length === 0) return null;
   537	  let last: CodexTurnFailedEvent | null = null;
   538	  let index = 0;
   539	  const len = text.length;
   540	  while (index <= len) {
   541	    let newline = text.indexOf('\n', index);
   542	    if (newline === -1) newline = len;
   543	    const line = text.slice(index, newline).trim();
   544	    index = newline + 1;
   545	    if (line.length > 0) {
   546	      let parsed: unknown;
   547	      try {
   548	        parsed = JSON.parse(line);
   549	      } catch {
   550	        parsed = undefined;
   551	      }
   552	      if (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) {
   553	        const event = parsed as Record<string, unknown>;
   554	        const type = Object.prototype.hasOwnProperty.call(event, 'type') ? event.type : undefined;
   555	        if (type === 'turn.failed') {
   556	          const error = Object.prototype.hasOwnProperty.call(event, 'error') ? event.error : undefined;
   557	          let message: string | null = null;
   558	          if (typeof error === 'object' && error !== null && !Array.isArray(error)) {
   559	            const errObj = error as Record<string, unknown>;
   560	            const m = Object.prototype.hasOwnProperty.call(errObj, 'message') ? errObj.message : undefined;
   561	            if (typeof m === 'string') message = m;
   562	          }
   563	          last = { eventType: 'turn.failed', message };
   564	        } else if (type === 'error') {
   565	          const m = Object.prototype.hasOwnProperty.call(event, 'message') ? event.message : undefined;
   566	          last = { eventType: 'error', message: typeof m === 'string' ? m : null };
   567	        }
   568	      }
   569	    }
   570	    if (newline === len) break;
   571	  }
   572	  return last;
   573	}
