   575	/** B-3ddc: hard cap (chars) on the sanitized turn_failed(<digest>) excerpt. */
   576	export const CODEX_TURN_FAILED_DIGEST_MAX_CHARS = 160;
   577	
   578	/** B-3ddc: depth cap when drilling a JSON-encoded message for the innermost error.message. */
   579	const CODEX_TURN_FAILED_NESTED_DEPTH_CAP = 4;
   580	
   581	/**
   582	 * B-3ddc: render the honest unavailable reason `turn_failed(<digest>)` for a
   583	 * scanned failure event. The digest is a short sanitized excerpt of the
   584	 * error message — deliberately human-readable (not a hash) so the ledger row
   585	 * itself names the failure:
   586	 *   - null/empty (after trim) message -> 'no_error_message';
   587	 *   - a mess

age that itself parses as a JSON object (the observed B-3928
   588	 *     payload string-encodes a nested 400 body) is drilled to the INNERMOST
   589	 *     `error.message` string (bounded depth; falls back to the original
   590	 *     message when nothing extractable is found);
   591	 *   - control characters (\n \r \t, NUL, DEL) and whitespace runs collapse to
   592	 *     a single space; the result is hard-capped at
   593	 *     CODEX_TURN_FAILED_DIGEST_MAX_CHARS total with a trailing '…' when cut.
   594	 */
   595	export function codexTurnFailedReason(failure: CodexTurnFailedEvent): string {
   596	  return `turn_failed(${codexTurnFailedDigest(failure.message)})`;
   597	}
   598	
   599	function codexTurnFailedDigest(message: string | null): string {
   600	  if (message === null || message.trim().length === 0) return 'no_error_message';
   601	  let text = message;
   602	  // Drill: when the message itself parses as a JSON object, descend through
   603	  // own `error` object properties (bounded depth) and prefer the DEEPEST own
   604	  // `message` string found; keep the original message when none is extractable.
   605	  let parsed: unknown;
   606	  try {
   607	    parsed = JSON.parse(text);
   608	  } catch {
   609	    parsed = undefined;
   610	  }
   611	  if (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) {
   612	    let node = parsed as Record<string, unknown>;
   613	    let deepest: string | null = null;
   614	    for (let depth = 0; depth < CODEX_TURN_FAILED_NESTED_DEPTH_CAP; depth++) {
   615	      const m = Object.prototype.hasOwnProperty.call(node, 'message') ? node.message : undefined;
   616	      if (typeof m === 'string') deepest = m;
   617	      const err = Object.prototype.hasOwnProperty.call(node, 'error') ? node.error : undefined;
   618	      if (typeof err !== 'object' || err === null || Array.isArray(err)) break;
   619	      node = err as Record<string, unknown>;
   620	    }
   621	    if (deepest !== null && deepest.trim().length > 0) text = deepest;
   622	  }
   623	  // Sanitize: every control-character/whitespace run becomes a single space,
   624	  // then B-3ddc (codex round-1 F2) neutralize parentheses — '(' -> '[' and
   625	  // ')' -> ']' — so an error.message containing ')' or '(' can never close or
   626	  // reopen the enclosing turn_failed(...) reason delimiters (a delimiter-
   627	  // injection guard). The pinned B-3928 upgrade message contains no parens, so
   628	  // its expected reason string is unchanged.
   629	  const sanitized = text.replace(/[\u0000-\u001f\u007f\s]+/g, ' ').replace(/\(/g, '[').replace(/\)/g, ']').trim();
   630	  if (sanitized.length === 0) return 'no_error_message';
   631	  if (sanitized.length > CODEX_TURN_FAILED_DIGEST_MAX_CHARS) {
   632	    return `${sanitized.slice(0, CODEX_TURN_FAILED_DIGEST_MAX_CHARS - 1)}…`;
   633	  }
   634	  return sanitized;
   635	}
